    affiliateLinks: [{"label": "キュレル 潤浸保湿 ジェルローション（花王）（楽天）", "label_en": "Curel Moisture Gel Lotion (Kao) (Rakuten)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00s6cvn.kll756cb.g00s6cvn.kll761ab/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fnanohanadrg%2F4901301321091%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fnanohanadrg%2Fi%2F10000960%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "アネッサ パーフェクトUV マイルドミルク（資生堂）（楽天）", "label_en": "Anessa Perfect UV Mild Milk (Shiseido) (Rakuten)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00t269n.kll75267.g00t269n.kll761d2/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Farianakosume%2F4909978147105-ra%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Farianakosume%2Fi%2F10006764%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}],
